package main

import (
	"fmt"
	"net/http"
	"os"
)

const logDir = "/var/log/adminpanel/"

// downloadLogHandler permette a un amministratore di scaricare
// i file di log dell'applicazione dal pannello interno.
func downloadLogHandler(w http.ResponseWriter, r *http.Request) {
	// Il nome del file richiesto arriva direttamente dalla query string
	fileName := r.URL.Query().Get("file")
	if fileName == "" {
		http.Error(w, "parametro 'file' mancante", http.StatusBadRequest)
		return
	}

	// VULNERABILITÀ: il path del file viene costruito concatenando
	// l'input utente senza alcuna validazione o canonicalizzazione
	fullPath := logDir + fileName

	data, err := os.ReadFile(fullPath)
	if err != nil {
		http.Error(w, "file non trovato: "+fullPath, http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "text/plain")
	w.Header().Set("Content-Disposition", "attachment; filename="+fileName)
	w.Write(data)
}

func main() {
	http.HandleFunc("/admin/logs/download", downloadLogHandler)
	fmt.Println("Admin panel in ascolto su :8080")
	http.ListenAndServe(":8080", nil)
}

