package main

import (
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

const logDir = "/var/log/adminpanel"

// Allowlist: solo nomi semplici, alfanumerici, con estensione .log.
// Esclude per costruzione '/', '\', '..' e null byte.
var validFileName = regexp.MustCompile(`^[a-zA-Z0-9_-]+\.log$`)

func downloadLogHandler(w http.ResponseWriter, r *http.Request) {
	fileName := r.URL.Query().Get("file")

	// 1. Validazione con allowlist: rifiuta tutto ciò che non è atteso
	if !validFileName.MatchString(fileName) {
		http.Error(w, "nome file non valido", http.StatusBadRequest)
		return
	}

	// 2. Costruzione e canonicalizzazione del path
	fullPath := filepath.Join(logDir, filepath.Base(fileName))
	cleanPath := filepath.Clean(fullPath)

	// 3. Difesa in profondità: il path risolto DEVE restare nella base dir
	if !strings.HasPrefix(cleanPath, logDir+string(os.PathSeparator)) {
		http.Error(w, "accesso non consentito", http.StatusForbidden)
		return
	}

	data, err := os.ReadFile(cleanPath)
	if err != nil {
		// 4. Errore generico: non rivelare path o dettagli del filesystem
		http.Error(w, "file non trovato", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.Header().Set("Content-Disposition", "attachment; filename="+fileName)
	w.Write(data)
}

func main() {
	http.HandleFunc("/admin/logs/download", downloadLogHandler)
	fmt.Println("Admin panel in ascolto su :8080")
	http.ListenAndServe(":8080", nil)
}

