import base64
import hashlib
from Crypto.Cipher import AES

PASSWORD = b"supersegreta"   # password condivisa tra gli utenti della chat


class MessageCipher:
    """Cifra i messaggi della chat prima dell'invio tramite il server."""

    def __init__(self):
        # Chiave AES-128 derivata dalla password con un singolo MD5
        self.key = hashlib.md5(PASSWORD).digest()
        # IV fisso, riutilizzato identico per OGNI messaggio
        self.iv = b"\x00" * 16

    def encrypt_message(self, plaintext: str) -> str:
        cipher = AES.new(self.key, AES.MODE_CBC, self.iv)
        data = self._pad(plaintext.encode("utf-8"))
        return base64.b64encode(cipher.encrypt(data)).decode()

    def decrypt_message(self, b64_ciphertext: str) -> str:
        cipher = AES.new(self.key, AES.MODE_CBC, self.iv)
        data = cipher.decrypt(base64.b64decode(b64_ciphertext))
        return self._unpad(data).decode("utf-8")

    @staticmethod
    def _pad(data: bytes) -> bytes:
        n = 16 - len(data) % 16
        return data + bytes([n]) * n

    @staticmethod
    def _unpad(data: bytes) -> bytes:
        return data[:-data[-1]]


def broadcast(sender: str, message: str) -> None:
    print(f"[{sender}] {message}")   # placeholder per l'invio via WebSocket


def handle_message(sender: str, text: str, cipher: MessageCipher) -> None:
    encrypted = cipher.encrypt_message(text)
    broadcast(sender, encrypted)     # il server inoltra solo il "cifrato"

