use std::fs;
use std::path::{Path, PathBuf};

const INVOICE_DIR: &str = "/var/legacy_orders/invoices";
const MAX_ORDER_ID_LEN: usize = 32;

/// Allowlist: il formato reale degli ID ordine (es. ORD-2019-001237).
/// Niente '/', NUL, né path assoluti sono rappresentabili.
fn is_valid_order_id(order_id: &str) -> bool {
    !order_id.is_empty()
        && order_id.len() <= MAX_ORDER_ID_LEN
        && order_id
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'-')
}

pub fn get_invoice(order_id: &str) -> Result<String, String> {
    // 1. Validazione allowlist: si accetta solo ciò che è notoriamente valido.
    if !is_valid_order_id(order_id) {
        return Err("invalid order id".to_string());
    }

    // 2. Costruzione del path: l'input ormai non può alterare la directory.
    let base = Path::new(INVOICE_DIR)
        .canonicalize()
        .map_err(|_| "service unavailable".to_string())?;
    let candidate: PathBuf = base.join(order_id);

    // 3. Difesa in profondità: canonicalize risolve i symlink e si verifica
    //    che il file reale sia ancora confinato nella directory base.
    //    (Un confronto lessicale su path non canonici non offrirebbe garanzie.)
    let resolved = candidate
        .canonicalize()
        .map_err(|_| "invoice not found".to_string())?;
    if !resolved.starts_with(&base) || !resolved.is_file() {
        return Err("invoice not found".to_string());
    }

    // 4. Errori generici: nessuna informazione sul filesystem all'esterno.
    fs::read_to_string(&resolved).map_err(|_| "invoice not found".to_string())
}

