    public String step1(@ModelAttribute("order") Order o) { return "payment"; }

    @PostMapping("/step2")   // il form HTML espone SOLO i dati di pagamento
    public String step2(@ModelAttribute("order") Order o) { return "review"; }

    @PostMapping("/confirm")
    public String confirm(@ModelAttribute("order") Order o, SessionStatus s) {
        if (o.isPaymentVerified() && o.getCustomer().getId() != null) {
            orders.save(o);              // (2) flush dello stato manipolato
            s.setComplete();
            return "thanks";
        }
        return "review";
    }
