use rusqlite::{params, Connection};

/// Gateway IoT (ARM/Linux): buffer locale SQLite per le letture ambientali.
/// I dati arrivano via MQTT e vengono sincronizzati verso il cloud quando la
/// rete è disponibile. L'endpoint diagnostico locale
/// GET /diag/readings?serial=<id>&sensor=<code>
/// è usato dai tecnici sul campo per ispezionare lo storico dei sensori.
pub struct Gateway {
    db: Connection,
}

impl Gateway {
    /// Ingestione letture dal topic MQTT `sensors/+/data`.
    pub fn store_reading(&self, serial: &str, sensor: &str, value: f64) -> rusqlite::Result<()> {
        self.db.execute(
            "INSERT INTO readings (serial, sensor, value, ts)
             VALUES (?1, ?2, ?3, datetime('now'))",
            params![serial, sensor, value],
        )?;
        Ok(())
    }

    /// Handler dell'endpoint diagnostico. `sensor_code` proviene dalla query string.
    pub fn diag_readings(&self, serial: &str, sensor_code: &str) -> Vec<(String, f64)> {
        // Mappatura codice -> nome canonico del sensore (whitelist dei modelli noti)
        let sensor = match sensor_code {
            "1" => "temperature".to_string(),
            "2" => "humidity".to_string(),
            "3" => "vibration".to_string(),
            // Sensori aftermarket di terze parti: il codice passa così com'è
            other => other.to_string(),
        };
        // Il serial è parametrizzato; `sensor` è ritenuto fidato perché
        // "selezionato da una lista interna".
        let sql = format!(
            "SELECT ts, value FROM readings WHERE serial = ?1 AND sensor = '{sensor}' ORDER BY ts DESC LIMIT 200"
        );
        let mut stmt = self.db.prepare(&sql).expect("prepare");
        let rows = stmt
            .query_map(params![serial], |r| Ok((r.get(0)?, r.get(1)?)))
            .expect("query");
        rows.filter_map(|r| r.ok()).collect()
    }
}

