use rusqlite::{params, Connection, OpenFlags};

pub struct Gateway {
    db: Connection,
}

#[derive(Debug)]
pub enum DiagError {
    UnknownSensor,
    InvalidSerial,
    Internal, // errore DB: loggato internamente, mai restituito gretto al client
}

impl Gateway {
    /// La connessione diagnostica è aperta in SOLA LETTURA (minimo privilegio).
    pub fn open_readonly(path: &str) -> rusqlite::Result<Self> {
        let db = Connection::open_with_flags(path, OpenFlags::SQLITE_OPEN_READ_ONLY)?;
        Ok(Self { db })
    }

    pub fn diag_readings(&self, serial: &str, sensor_code: &str)
        -> Result<Vec<(String, f64)>, DiagError>
    {
        // (a) Whitelist CHIUSA: nessun pass-through. I sensori di terze parti
        //     vengono censiti esplicitamente in una tabella di registry, non
        //     accettando input arbitrario.
        let sensor = match sensor_code {
            "1" => "temperature",
            "2" => "humidity",
            "3" => "vibration",
            _ => return Err(DiagError::UnknownSensor),
        };

        // (b) Validazione del formato del seriale (defense in depth).
        if serial.is_empty() || serial.len() > 16
            || !serial.chars().all(|c| c.is_ascii_alphanumeric())
        {
            return Err(DiagError::InvalidSerial);
        }

        // (c) ENTRAMBI i valori sono parametrizzati: i dati non vengono mai
        //     interpretati come SQL.
        let mut stmt = self.db
            .prepare(
                "SELECT ts, value FROM readings
                 WHERE serial = ?1 AND sensor = ?2
                 ORDER BY ts DESC LIMIT 200",
            )
            .map_err(|e| { log::error!("prepare: {e}"); DiagError::Internal })?;

        let rows = stmt
            .query_map(params![serial, sensor], |r| Ok((r.get(0)?, r.get(1)?)))
            .map_err(|e| { log::error!("query: {e}"); DiagError::Internal })?;

        Ok(rows.filter_map(|r| r.ok()).collect())
    }
}

