        // "selezionato da una lista interna".
        let sql = format!(
            "SELECT ts, value FROM readings WHERE serial = ?1 AND sensor = '{sensor}' ORDER BY ts DESC LIMIT 200"
        );
        let mut stmt = self.db.prepare(&sql).expect("prepare");
