import express from 'express';
import crypto from 'crypto';

const app = express();
app.use(express.json());

// Chiave caricata da variabile d'ambiente / secret manager — MAI nel codice sorgente
const ENCRYPTION_KEY = Buffer.from(process.env.DOC_ENCRYPTION_KEY ?? '', 'base64');
if (ENCRYPTION_KEY.length !== 32) {
  throw new Error('DOC_ENCRYPTION_KEY deve essere una chiave a 256 bit codificata in base64');
}

const documentStore: { [patientId: string]: string } = {};

function encryptDocument(plainText: string): string {
  const iv = crypto.randomBytes(12); // IV casuale e UNICO per ogni cifratura (96 bit, standard GCM)
  const cipher = crypto.createCipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
  const encrypted = Buffer.concat([cipher.update(plainText, 'utf8'), cipher.final()]);
  const authTag = cipher.getAuthTag(); // 16 byte: garantisce integrità e autenticità
  // Formato salvato: iv (12B) | authTag (16B) | ciphertext
  return Buffer.concat([iv, authTag, encrypted]).toString('base64');
}

function decryptDocument(payload: string): string {
  const data = Buffer.from(payload, 'base64');
  const iv = data.subarray(0, 12);
  const authTag = data.subarray(12, 28);
  const cipherText = data.subarray(28);
  const decipher = crypto.createDecipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
  decipher.setAuthTag(authTag); // se i dati sono stati manomessi, final() lancia un'eccezione
  return decipher.update(cipherText, undefined, 'utf8') + decipher.final('utf8');
}

app.post('/api/documents', (req, res) => {
  const { patientId, medicalReport } = req.body;
  documentStore[patientId] = encryptDocument(medicalReport);
  res.status(201).json({ patientId }); // non restituire il ciphertext: niente oracolo
});

app.get('/api/documents/:patientId', (req, res) => {
  const stored = documentStore[req.params.patientId];
  if (!stored) return res.status(404).json({ error: 'Documento non trovato' });
  try {
    res.json({ patientId: req.params.patientId, medicalReport: decryptDocument(stored) });
  } catch {
    res.status(500).json({ error: 'Verifica di integrità fallita: documento manomesso' });
  }
});

app.listen(3000, () => console.log('Server avviato sulla porta 3000'));

