/* seal-token-fixed.c — AES-256-GCM, nonce da CSPRNG, fail-closed */
#include <aws/lambda-runtime.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/crypto.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define KEY_LEN 32   /* AES-256        */
#define NONCE_LEN 12 /* 96 bit: GCM    */
#define TAG_LEN 16
#define MAX_PT 512

static uint8_t g_key[KEY_LEN];

static int crypto_init(void) {                  /* chiave hex da Secrets Manager */
    const char *hex = getenv("SEAL_KEY");
    if (hex == NULL || strlen(hex) != KEY_LEN * 2) return -1;
    for (size_t i = 0; i < KEY_LEN; i++)
        if (sscanf(hex + 2*i, "%2hhx", &g_key[i]) != 1) return -1;
    return 0;
}

static int seal(const uint8_t *pt, size_t pt_len, uint8_t *out, size_t *out_len) {
    if (pt_len == 0 || pt_len > MAX_PT) return -1;        /* bound check */
    uint8_t nonce[NONCE_LEN];
    if (RAND_bytes(nonce, NONCE_LEN) != 1) return -1;     /* CSPRNG per messaggio */
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) return -1;
    int len = 0, tot = 0, rc = -1;
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, NULL, NULL) != 1) goto out;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, NONCE_LEN, NULL) != 1) goto out;
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, g_key, nonce) != 1) goto out;
    if (EVP_EncryptUpdate(ctx, out, &len, pt, (int)pt_len) != 1) goto out;
    tot = len;
    if (EVP_EncryptFinal_ex(ctx, out + tot, &len) != 1) goto out;
    tot += len;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, TAG_LEN, out + tot) != 1) goto out;
    tot += TAG_LEN;
    memcpy(out + tot, nonce, NONCE_LEN);                  /* formato: ct||tag||nonce */
    *out_len = (size_t)tot + NONCE_LEN;
    rc = 0;
out:
    EVP_CIPHER_CTX_free(ctx);
    return rc;
}

static invocation_response handler(invocation_request req) {
    static char hex[2 * (MAX_PT + TAG_LEN + NONCE_LEN) + 1];
    uint8_t sealed[MAX_PT + TAG_LEN + NONCE_LEN];
    size_t n = 0;
    if (seal((const uint8_t *)req.payload, strlen(req.payload), sealed, &n) != 0)
        return failure("invalid input", "ValidationError");
    for (size_t i = 0; i < n; i++) snprintf(hex + 2*i, 3, "%02x", sealed[i]);
    return success(hex, "application/octet-stream");
}

int main(void) {
    if (crypto_init() != 0) return 1;                     /* fail-closed all'init */
    lambda_runtime_init(NULL);
    return run_handler(handler);
}

