}
static size_t seal(const char *pt, uint8_t *out) {  /* out = ct || iv */
    uint8_t iv[16];
    for (size_t i = 0; i < sizeof iv; i++)
        iv[i] = (uint8_t)(rand() & 0xFF);           /* IV "random" per AES-CTR */
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int len = 0, tot = 0;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, g_key, iv);
    EVP_EncryptUpdate(ctx, out, &len, (const uint8_t *)pt, (int)strlen(pt));
    tot = len;
    EVP_EncryptFinal_ex(ctx, out + tot, &len);
    tot += len;
    EVP_CIPHER_CTX_free(ctx);
    memcpy(out + tot, iv, sizeof iv);
    return (size_t)tot + sizeof iv;
}
static invocation_response handler(invocation_request req) {
    static char hex[2200];
    uint8_t sealed[1088];
    size_t n = seal(req.payload, sealed);
    for (size_t i = 0; i < n; i++) snprintf(hex + 2*i, 3, "%02x", sealed[i]);
    return success(hex, "application/octet-stream");
