// handleToken implementa il token endpoint (RFC 6749 §4.1.3): scambia un
// authorization code con un access token. oauth_codes.redirect_uri viene
// popolato dall'endpoint /authorize leggendo r.URL.Query().Get("redirect_uri")
// (che decodifica il percent-encoding); alla registrazione del client è stato
// validato solo l'host. Il valore è quindi considerato "fidato"...
func (s *Server) handleToken(w http.ResponseWriter, r *http.Request) {
	code := r.PostFormValue("code")
	clientID := r.PostFormValue("client_id")
	clientSecret := r.PostFormValue("client_secret")

	// La SELECT sul code è correttamente parametrizzata.
	var storedRedirect string
	err := s.db.QueryRow(
		`SELECT redirect_uri FROM oauth_codes WHERE code = $1`, code,
	).Scan(&storedRedirect)
	if err != nil {
		oauthError(w, "invalid_grant")
		return
	}

	// VULNERABILE: storedRedirect (tainted, second-order) è concatenato.
	query := fmt.Sprintf(`
		SELECT c.client_secret_hash, k.user_id
		FROM oauth_clients c JOIN oauth_codes k ON k.client_id = c.client_id
		WHERE k.code = $1 AND k.redirect_uri = '%s'`, storedRedirect)

	var secretHash, userID string
	if err := s.db.QueryRow(query, code).Scan(&secretHash, &userID); err != nil {
		oauthError(w, "invalid_grant")
		return
	}
	if bcrypt.CompareHashAndPassword([]byte(secretHash), []byte(clientSecret)) != nil {
		oauthError(w, "invalid_client")
		return
	}
	accessToken, _ := s.mintAccessToken(userID, clientID)
	json.NewEncoder(w).Encode(map[string]string{"access_token": accessToken, "token_type": "Bearer"})
}

benchmark.secure_patch_code:
func (s *Server) handleToken(w http.ResponseWriter, r *http.Request) {
	code := r.PostFormValue("code")
	clientID := r.PostFormValue("client_id")
	clientSecret := r.PostFormValue("client_secret")
	presentedRedirect := r.PostFormValue("redirect_uri")

	// (1) TUTTI i valori sono bind parameter — anche quelli provenienti dal DB.
	var storedRedirect, secretHash, userID string
	err := s.db.QueryRow(`
		SELECT k.redirect_uri, c.client_secret_hash, k.user_id
		FROM oauth_codes k JOIN oauth_clients c ON c.client_id = k.client_id
		WHERE k.code = $1
		  AND k.client_id = $2
		  AND k.expires_at > now()
		  AND k.consumed = false`, code, clientID,
	).Scan(&storedRedirect, &secretHash, &userID)
	if err != nil {
		oauthError(w, "invalid_grant")
		return
	}

	// (2) Confronto del redirect_uri a livello applicativo, exact match
	//     (RFC 6749 §4.1.3), mai nel testo SQL.
	if presentedRedirect != storedRedirect {
		oauthError(w, "invalid_grant")
		return
	}
	if bcrypt.CompareHashAndPassword([]byte(secretHash), []byte(clientSecret)) != nil {
		oauthError(w, "invalid_client")
		return
	}

	// (3) Consumo atomico del code (anti-replay, RFC 6749 §4.1.2).
	res, _ := s.db.Exec(`UPDATE oauth_codes SET consumed = true WHERE code = $1 AND consumed = false`, code)
	if n, _ := res.RowsAffected(); n != 1 {
		oauthError(w, "invalid_grant")
		return
	}

	accessToken, _ := s.mintAccessToken(userID, clientID)
	json.NewEncoder(w).Encode(map[string]string{"access_token": accessToken, "token_type": "Bearer"})
}

