// build-upload.js — versione corretta: nessun segreto nel sorgente
const { execSync } = require('child_process');
const https = require('https');
const fs = require('fs');

// Fail-fast: il job CI fallisce subito se il secret non è stato iniettato
function requireEnv(name) {
  const value = process.env[name];
  if (!value) {
    console.error(`[CI] ERRORE: variabile d'ambiente ${name} non impostata.`);
    process.exit(1);
  }
  return value;
}

// I segreti arrivano dal Secret Store della piattaforma CI
// (GitHub Actions Secrets / GitLab CI/CD Variables masked+protected),
// iniettati a runtime come variabili d'ambiente del job.
const ARTIFACTORY_TOKEN = requireEnv('ARTIFACTORY_TOKEN');
const SLACK_WEBHOOK_URL = requireEnv('SLACK_WEBHOOK_URL');
const REGISTRY_HOST = process.env.REGISTRY_HOST || 'artifacts.internal.example.com';

function buildProject() {
  console.log('[CI] Avvio build...');
  execSync('npm run build', { stdio: 'inherit' });
}

function uploadArtifact(filePath) {
  const data = fs.readFileSync(filePath);
  const options = {
    hostname: REGISTRY_HOST,
    path: '/artifactory/api/npm/npm-local/myapp-1.4.2.tgz',
    method: 'PUT',
    headers: {
      'Authorization': 'Bearer ' + ARTIFACTORY_TOKEN, // solo in memoria, mai nel repo
      'Content-Type': 'application/octet-stream',
      'Content-Length': data.length
    }
  };
  const req = https.request(options, (res) => {
    console.log('[CI] Upload completato, status:', res.statusCode);
  });
  req.write(data);
  req.end();
}

// Niente curl via shell: uso HTTPS nativo, il segreto non finisce
// mai in una stringa di comando (evita leak via process list / log)
function notifyTeam(message) {
  const payload = JSON.stringify({ text: message });
  const url = new URL(SLACK_WEBHOOK_URL);
  const req = https.request({
    hostname: url.hostname,
    path: url.pathname,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Content-Length': payload.length }
  });
  req.write(payload);
  req.end();
